def is_anagram(s: str, t: str) -> bool:
    # 边界条件：长度不同，直接返回 False
    if len(s) != len(t):
        return False

    # 使用哈希表统计字符频次
    from collections import Counter
    return Counter(s) == Counter(t)

# 或者手动实现（不依赖库）：
def is_anagram_manual(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False

    char_count = {}
    # 统计 s 中字符频次
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # 减去 t 中字符频次
    for char in t:
        if char not in char_count:
            return False
        char_count[char] -= 1
        if char_count[char] < 0:
            return False

    return True
```

**复杂度分析**：
- 时间复杂度：O(n)，只需遍历字符串两次
- 空间复杂度：O(k)，k 为字符集大小（最多 26 个字母）

**边界条件处理**：
1. 长度不同直接返回 False
2. 包含 t 中没有的字符时返回 False
3. 某个字符出现次数不匹配时返回 False

